1	import { useQuery } from '@tanstack/react-query';
2	import { invoicesKey, fetchInvoices, INVOICE_SORT_PARAM, type Invoice } from './queries';
3	import { InvoiceRow } from '../../slots/defs/invoiceRow';
4	import { InvoicesToolbar } from '../../slots/defs/invoicesToolbar';
5	import { useSearchParam, asString } from '../../url/useSearchParam';
6	import { formatMoney } from '../../ui/money';
7	
8	// A project's invoices list plus the derived total. Queries for itself under ['invoices', projectId]
9	// — never handed its data by a parent (CLAUDE.md rule 5). Amounts render with 2 decimals; the total
10	// is a client-side aggregate of the same rows, so it stays in step with them for free.
11	export function InvoicesTable({ projectId }: { projectId: number }) {
12	  const { data: invoices } = useQuery({
13	    queryKey: invoicesKey(projectId),
14	    queryFn: () => fetchInvoices(projectId),
15	  });
16	  // Which sort is active lives in the URL (CLAUDE.md rule 4); the sort control owns the key and this
17	  // list reads it. Due dates are stored as ISO strings, so a plain string compare is chronological.
18	  const [sort] = useSearchParam(INVOICE_SORT_PARAM, asString);
19	
20	  if (!invoices) {
21	    return null;
22	  }
23	
24	  const rows =
25	    sort === 'due'
26	      ? [...invoices].sort((a, b) => (a.dueDate ?? '').localeCompare(b.dueDate ?? ''))
27	      : invoices;
28	
29	  const total = invoices.reduce((sum, invoice) => sum + Number(invoice.amount), 0);
30	
31	  return (
32	    <>
